class PaymentMethod(ABC):
    @abstractmethod
    def process_payment(self, order, security_code: str):
        pass

class CreditCardPayment(PaymentMethod):
    def process_payment(self, order, security_code: str):
        print("Processing credit card payment")
        print(f"Verifying security code: {security_code}")
        order.status = "paid"

class PaymentProcessor(PaymentProcessor):
    def __init__(self, strategy: PaymentMethod):
        self.strategy = strategy

    def pay_order(self, order, security_code: str):
        self.strategy.process_payment(order, security_code)
